// Import necessary React hooks and components
import React, { useEffect, useState } from "react";
import AdminNavbar from "../Components/AdminNavbar"; // Admin-specific navigation
import Footer from "../Components/Footer"; // Footer component
import "../styles/AdminPages.css"; // Admin dashboard styling
import API_BASE_URL from "../config"; // API base URL
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart, Bar, Legend
} from "recharts"; // Recharts for graphs

// Functional component for Subscription Sales page
const SubscriptionSales = () => {
  const [sales, setSales] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch subscription sales from backend when page loads
  useEffect(() => {
    fetch(`${API_BASE_URL}/api/admin/subscription-sales`)
      .then((res) => res.json())
      .then((data) => {
        setSales(data);
        setLoading(false);
      })
      .catch((err) => console.error("Failed to load subscription sales:", err));
  }, []);

  // Calculate total revenue from subscriptions
  const totalRevenue = sales.reduce((sum, sale) => sum + parseFloat(sale.price), 0);

  // Prepare data for charts
  const salesByDate = sales.map(sale => ({
    date: new Date(sale.subscribed_at).toLocaleDateString(),
    revenue: parseFloat(sale.price),
  }));

  const salesByPlan = Object.values(
    sales.reduce((acc, sale) => {
      acc[sale.plan_name] = acc[sale.plan_name] || { plan: sale.plan_name, total: 0 };
      acc[sale.plan_name].total += parseFloat(sale.price);
      return acc;
    }, {})
  );

  // JSX rendering the page
  return (
    <div className="dashboard-wrapper" style={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <AdminNavbar />
      <main className="dashboard-main" style={{ flex: 1, padding: "40px" }}>
        <h2>Subscription Sales</h2>

        {/* Loading Spinner */}
        {loading ? (
          <p>Loading subscription sales...</p>
        ) : (
          <>
            {/* Total Revenue */}
            <div style={{ marginBottom: "30px" }}>
              <h3>Total Subscription Revenue: ${totalRevenue.toFixed(2)}</h3>
            </div>

            {/* Sales Over Time Chart */}
            <div style={{ marginBottom: "40px", width: "100%", height: 300 }}>
              <h4>Revenue Over Time</h4>
              <ResponsiveContainer>
                <LineChart data={salesByDate}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="date" />
                  <YAxis />
                  <Tooltip />
                  <Line type="monotone" dataKey="revenue" stroke="#4f46e5" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
            </div>

            {/* Revenue by Plan Type */}
            <div style={{ marginBottom: "40px", width: "100%", height: 300 }}>
              <h4>Revenue by Plan Type</h4>
              <ResponsiveContainer>
                <BarChart data={salesByPlan}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="plan" />
                  <YAxis />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="total" fill="#22c55e" />
                </BarChart>
              </ResponsiveContainer>
            </div>

            {/* Sales List */}
            <div className="favorites-grid">
              {sales.map((sale) => (
                <div key={sale.id} className="favorite-card">
                  <h4>User ID: {sale.user_id}</h4>
                  <p><strong>Plan:</strong> {sale.plan_name}</p>
                  <p><strong>Price:</strong> ${parseFloat(sale.price).toFixed(2)}</p>
                  <p><strong>Subscribed On:</strong> {new Date(sale.subscribed_at).toLocaleString()}</p>
                </div>
              ))}
            </div>
          </>
        )}
      </main>
      <Footer />
    </div>
  );
};

// Export the component
export default SubscriptionSales;
